"""Migration DAG dependency resolver and topological planner."""

from typing import Dict, List, Set
from migration import MigrationStep


class MigrationDAG:
    def __init__(self, steps: Dict[str, MigrationStep]):
        self.steps = steps

    def get_forward_order(self) -> List[str]:
        # Standard Kahn topological sort
        in_degree = {k: 0 for k in self.steps}
        dependents: Dict[str, List[str]] = {k: [] for k in self.steps}
        for name, step in self.steps.items():
            for dep in step.dependencies:
                if dep in in_degree:
                    in_degree[name] += 1
                    dependents[dep].append(name)
        queue = [k for k, d in in_degree.items() if d == 0]
        order = []
        while queue:
            curr = queue.pop(0)
            order.append(curr)
            for dep in dependents[curr]:
                in_degree[dep] -= 1
                if in_degree[dep] == 0:
                    queue.append(dep)
        return order

    def get_rollback_order_for(self, target_migration: str) -> List[str]:
        # Must rollback target_migration and ALL migrations that depend on it
        # BUG: Only returns target_migration itself without recursively finding
        # all downstream dependent migrations in reverse dependency order!
        if target_migration not in self.steps:
            return []
        return [target_migration]

repo_files.executor.py:
"""Migration SQL executor and state tracker."""

from typing import Any, Dict, List
from migration import MigrationStep


class MigrationExecutor:
    def __init__(self, steps: Dict[str, MigrationStep]):
        self.steps = steps
        self.applied_history: List[str] = []

    def apply_migration(self, name: str) -> None:
        step = self.steps[name]
        for dep in step.dependencies:
            if not self.steps[dep].applied:
                raise RuntimeError(f"Cannot apply {name}: dependency {dep} not applied")
        step.applied = True
        self.applied_history.append(name)

    def rollback_migration(self, name: str) -> None:
        step = self.steps[name]
        # Check if any currently applied migration depends on this one
        for other_name, other in self.steps.items():
            if other.applied and name in other.dependencies:
                raise RuntimeError(f"Cannot rollback {name}: active migration {other_name} depends on it")
        step.applied = False
        if name in self.applied_history:
            self.applied_history.remove(name)

repo_files.engine.py:
"""High level migration engine orchestrating apply and rollback flows."""

from typing import Dict, List
from dependency_graph import MigrationDAG
from executor import MigrationExecutor
from migration import MigrationStep


class MigrationEngine:
    def __init__(self, steps: Dict[str, MigrationStep]):
        self.steps = steps
        self.dag = MigrationDAG(steps)
        self.executor = MigrationExecutor(steps)

    def migrate_all(self) -> None:
        order = self.dag.get_forward_order()
        for m in order:
            if not self.steps[m].applied:
                self.executor.apply_migration(m)

    def rollback_target(self, target: str) -> None:
        # Plan rollback sequence
        rollback_steps = self.dag.get_rollback_order_for(target)
        for m in rollback_steps:
            if self.steps[m].applied:
                self.executor.rollback_migration(m)

