"""Migration DAG dependency resolver and topological planner."""

from typing import Dict, List, Set
from migration import MigrationStep


class MigrationDAG:
    def __init__(self, steps: Dict[str, MigrationStep]):
        self.steps = steps

    def get_forward_order(self) -> List[str]:
        in_degree = {k: 0 for k in self.steps}
        dependents: Dict[str, List[str]] = {k: [] for k in self.steps}
        for name, step in self.steps.items():
            for dep in step.dependencies:
                if dep in in_degree:
                    in_degree[name] += 1
                    dependents[dep].append(name)
        queue = [k for k, d in in_degree.items() if d == 0]
        order = []
        while queue:
            curr = queue.pop(0)
            order.append(curr)
            for dep in dependents[curr]:
                in_degree[dep] -= 1
                if in_degree[dep] == 0:
                    queue.append(dep)
        return order

    def get_rollback_order_for(self, target_migration: str) -> List[str]:
        if target_migration not in self.steps:
            return []
        # Find all downstream dependents recursively
        dependents_map: Dict[str, List[str]] = {k: [] for k in self.steps}
        for name, step in self.steps.items():
            for dep in step.dependencies:
                if dep in dependents_map:
                    dependents_map[dep].append(name)

        affected: Set[str] = set()
        def collect(m: str):
            affected.add(m)
            for child in dependents_map.get(m, []):
                if child not in affected:
                    collect(child)
        collect(target_migration)

        # Topological sort restricted to affected set, then reversed
        forward_order = self.get_forward_order()
        filtered_forward = [m for m in forward_order if m in affected]
        return list(reversed(filtered_forward))
